window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7421c951b77ff6b2"]={"versions": [{"id": "FIG-7421c951b77ff6b2", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Statistisches Säulendiagramm / Histogramm (Projekt- und Release-Management-Metrik, kein UML- oder Laufzeitdiagramm).\n</li><li><strong>Funktionaler Kontext:</strong> Quantitatives Übersichtsdiagramm innerhalb des Spezifikationsdokuments <code>AUTOSAR_FeatureDefinition</code> (Releases R2.1.20, R3.0.7, R3.1.5). Dient der Konsortiumssteuerung und Prioritätenallokation für Arbeitspakete und funktionale Anforderungen im Standardisierungsprozess.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Analysierte Grundgesamtheit:</strong> 62 spezifizierte AUTOSAR-Features im definierten Release-Scope.\n</li><li><strong>Klassifikationskategorien &amp; Verteilung:</strong>\n<ul class=\"fig-list\"><li><strong>P1 (Priority 1 – Zwingende Kernanforderungen):</strong> 33 Features (~53,2 %, rote Säule). Bildet die absolute Mehrheit des Funktionsumfangs.\n</li><li><strong>P2 (Priority 2 – Mittlere Dringlichkeit / Sekundärumfang):</strong> 12 Features (~19,4 %, blaue Säule).\n</li><li><strong>P3 (Priority 3 – Niedrige Dringlichkeit / Optional / Zukunfts-Scope):</strong> 17 Features (~27,4 %, graue Säule).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Disjunkte 1:1-Zuordnung der Feature-Definitionen zu diskreten Prioritätsstufen. Keine Software-Komponenten (SW-C), BSW-Module, Ports, Interfaces oder AUTOSAR-Metamodell-Stereotypen («atpSplitable», «isOfType») abgebildet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statische Dokumentations- und Prozessmetrik ohne Laufzeitbezug. Es existieren weder Tasks, Trigger, Bus-Botschaften noch Fehlerpfade (Det/Dem) oder Zustandsübergänge.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- &amp; Architekturvertrag:</strong> Keine direkte normative Bindung für C-Header, BSW-APIs, RTE-Generierung oder ECUC-Konfigurationsparameter.\n</li><li><strong>Konformitäts- und Roadmap-Relevanz:</strong> \n<ul class=\"fig-list\"><li><strong>P1-Features</strong> kennzeichnen den Mindestumfang für die offizielle AUTOSAR-Konformitätszertifizierung des jeweiligen Releases; Tier-1-Zulieferer und Stack-Vendors müssen diese Module prioritär vollständig implementieren.\n</li><li><strong>P2- und P3-Features</strong> dienen Entwicklern und Systemintegratoren als Orientierung für Feature-Stubs, optionale Stack-Pakete oder verzögerte Lieferstufen in Serienprojekten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-89094d25d4e28610", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Statistisches Säulendiagramm / Histogramm (Projekt- und Release-Management-Metrik, kein UML- oder Laufzeitdiagramm).\n</li><li><strong>Funktionaler Kontext:</strong> Quantitatives Übersichtsdiagramm innerhalb des Spezifikationsdokuments <code>AUTOSAR_FeatureDefinition</code> (Releases R2.1.20, R3.0.7, R3.1.5). Dient der Konsortiumssteuerung und Prioritätenallokation für Arbeitspakete und funktionale Anforderungen im Standardisierungsprozess.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Analysierte Grundgesamtheit:</strong> 62 spezifizierte AUTOSAR-Features im definierten Release-Scope.\n</li><li><strong>Klassifikationskategorien &amp; Verteilung:</strong>\n<ul class=\"fig-list\"><li><strong>P1 (Priority 1 – Zwingende Kernanforderungen):</strong> 33 Features (~53,2 %, rote Säule). Bildet die absolute Mehrheit des Funktionsumfangs.\n</li><li><strong>P2 (Priority 2 – Mittlere Dringlichkeit / Sekundärumfang):</strong> 12 Features (~19,4 %, blaue Säule).\n</li><li><strong>P3 (Priority 3 – Niedrige Dringlichkeit / Optional / Zukunfts-Scope):</strong> 17 Features (~27,4 %, graue Säule).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Disjunkte 1:1-Zuordnung der Feature-Definitionen zu diskreten Prioritätsstufen. Keine Software-Komponenten (SW-C), BSW-Module, Ports, Interfaces oder AUTOSAR-Metamodell-Stereotypen («atpSplitable», «isOfType») abgebildet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statische Dokumentations- und Prozessmetrik ohne Laufzeitbezug. Es existieren weder Tasks, Trigger, Bus-Botschaften noch Fehlerpfade (Det/Dem) oder Zustandsübergänge.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API- &amp; Architekturvertrag:</strong> Keine direkte normative Bindung für C-Header, BSW-APIs, RTE-Generierung oder ECUC-Konfigurationsparameter.\n</li><li><strong>Konformitäts- und Roadmap-Relevanz:</strong> \n<ul class=\"fig-list\"><li><strong>P1-Features</strong> kennzeichnen den Mindestumfang für die offizielle AUTOSAR-Konformitätszertifizierung des jeweiligen Releases; Tier-1-Zulieferer und Stack-Vendors müssen diese Module prioritär vollständig implementieren.\n</li><li><strong>P2- und P3-Features</strong> dienen Entwicklern und Systemintegratoren als Orientierung für Feature-Stubs, optionale Stack-Pakete oder verzögerte Lieferstufen in Serienprojekten.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-7421c951b77ff6b2", "to": "FIG-89094d25d4e28610", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
